	model: {
		provider: string;
		model: string;
		thinking: AgentThinkingLevel;
		temperature?: number;
		topP?: number;
		/** Candidates skipped during resolution, recorded for diagnostics only. */
		skippedCandidates?: ReadonlyArray<{ reference: string; reason: string }>;
