		baselineId?: string;
		baselineTree?: string;
		headCommit?: string;
		repoRoot?: string;
		/** Parent cwd relative to repoRoot; the child cwd is worktreePath + cwdOffset. */
		cwdOffset?: string;
		worktreePath?: string;
	};

	createdAt: string;
}

